pub fn gcp_scope_members(scopes: Rc<Vec<String>>) -> Rc<Vec<Rc<BindingMember>>> {
    Rc::new({ let mut __result = Vec::new(); for s in scopes.iter().cloned() { __result.push(Rc::new(BindingMember {
    identity: s.clone(),
})); } __result })
}

pub fn gcp_impersonated_binding_refusal(credential: Rc<GcpImpersonatedAccessCredential>, required_service_account: String, required_scopes: Rc<Vec<String>>) -> Option<Rc<BindingRefusal>> {
    {
        let held = credential.binding();
if (held.target_service_account() != required_service_account.clone()) {
            Some(Rc::new(BindingRefusal::BindingAxisMismatch {
    axis: gcp_impersonated_service_account_axis(),
    required: Rc::new(vec![Rc::new(BindingMember {
    identity: required_service_account.clone(),
})]),
    held: Rc::new(vec![Rc::new(BindingMember {
    identity: held.target_service_account(),
})]),
}))
        } else {
            if { let mut __found = false; for r in required_scopes.iter().cloned() { if !crate::std_algebra::contains(held.scopes(), r.clone(), |a, b| (a.clone() == b.clone())) { __found = true; break; } } __found } {
                Some(Rc::new(BindingRefusal::BindingAxisMismatch {
    axis: gcp_impersonated_scopes_axis(),
    required: gcp_scope_members(required_scopes.clone()),
    held: gcp_scope_members(held.scopes()),
}))
            } else {
                std::option::Option::None
            }
        }
}
}

pub fn gcp_impersonated_binding_same(a: Rc<GcpImpersonatedAccessCredential>, b: Rc<GcpImpersonatedAccessCredential>) -> bool {
    (((a.binding().target_service_account() == b.binding().target_service_account()) && !{ let mut __found = false; for s in a.binding().scopes().iter().cloned() { if !crate::std_algebra::contains(b.binding().scopes(), s.clone(), |x, y| (x.clone() == y.clone())) { __found = true; break; } } __found }) && !{ let mut __found = false; for s in b.binding().scopes().iter().cloned() { if !crate::std_algebra::contains(a.binding().scopes(), s.clone(), |x, y| (x.clone() == y.clone())) { __found = true; break; } } __found })
}

pub async fn gcp_impersonated_presentation(credential: Rc<GcpImpersonatedAccessCredential>, required_service_account: String, required_scopes: Rc<Vec<String>>, requirement: Rc<CredentialUseRequirement>, clk: &Clock) -> std::result::Result<Rc<CredentialPresentation>, std::boxed::Box<dyn std::error::Error>> {
    Ok(crate::std_credential_admission::present_credential(credential.secret_released_only_by_admission(), "GCP impersonated access token".to_string(), credential.validity(), gcp_impersonated_binding_refusal(credential.clone(), required_service_account.clone(), required_scopes), requirement, Rc::new(AccessRefusalLocation {
    profile: "extdeps.cloud.gcp.iam".to_string(),
    subject: required_service_account.clone(),
    action: "present an impersonated access token".to_string(),
    object: "GCP impersonated access token".to_string(),
}), &clk).await?)
}

